insert into public.dsa_problems
  (id, topic_id, title, difficulty, slug, description,
   examples, constraints, starter_code, hints, test_cases, editorial, solution_code,
   supported_languages, learning_grid_id, learning_topic_id, status, is_premium, sort_order)
select v.id, v.topic_id, v.title, v.difficulty, v.slug, v.description,
       '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '', '{}'::jsonb,
       array['python']::text[], g.id, tp.id, 'published', false, v.sort_order
from g, tp, (values
  ($g0$cp-genai-generative-vs-discriminative-models-1$g0$, null::text, $g0$Generative vs Discriminative Models — Coding Problem 1$g0$, 'Easy', $g0$genai-generative-vs-discriminative-models-1$g0$, $g0$Write a small Python program that demonstrates the main idea of **Generative vs Discriminative Models** using a simple example dataset or input.$g0$, 0),
