-- ===========================================================================
-- 6. VALIDATION — raise (never silently pass) if the import is short.
-- ===========================================================================
do $val$
declare v_g uuid; v_sec int; v_top int; v_con int; v_tst int; v_q int; v_prob int;
begin
  select id into v_g from public.learning_grids where lower(slug) = 'generative-ai';
  if v_g is null then raise exception 'genai seed: grid generative-ai missing after seed'; end if;
  select count(*) into v_sec from public.learning_sections where grid_id = v_g;
  select count(*) into v_top from public.learning_topics
    where grid_id = v_g and source_kind = 'generative_ai_tutorial';
  select count(*) into v_con from public.learning_contents c
    join public.learning_topics t on t.id = c.topic_id
   where t.grid_id = v_g and (c.metadata ->> 'source') = 'generative_ai_seed';
  select count(*) into v_tst from public.practice_tests
   where learning_grid_id = v_g and id like 'mt-genai-%';
  select count(*) into v_q from public.test_questions q
    join public.practice_tests p on p.id = q.test_id
   where p.learning_grid_id = v_g and p.id like 'mt-genai-%';
  select count(*) into v_prob from public.dsa_problems
   where learning_grid_id = v_g and topic_id is null and id like 'cp-genai-%';
  if v_sec  <> 17   then raise exception 'genai seed: expected 17 sections, got %', v_sec; end if;
  if v_top  <> 207 then raise exception 'genai seed: expected 207 topics, got %', v_top; end if;
  if v_con  <> 207 then raise exception 'genai seed: expected 207 content blocks, got %', v_con; end if;
  if v_tst  <> 206 then raise exception 'genai seed: expected 206 mock tests, got %', v_tst; end if;
  if v_q    <> 2060 then raise exception 'genai seed: expected 2060 questions, got %', v_q; end if;
  if v_prob <> 336 then raise exception 'genai seed: expected 336 coding problems, got %', v_prob; end if;
  raise notice 'genai seed OK: grid %, % sections, % topics, % contents, % tests, % questions, % problems',
    v_g, v_sec, v_top, v_con, v_tst, v_q, v_prob;
end
$val$;

notify pgrst, 'reload schema';
